lf.assertEqual(cache.get(\"missing\", now=0, default=\"\"), \"\")\n\n    def test_get_returns_default_for_expired_with_custom_default(self):\n        cache = Cache()\n        cache.put(\"a\", \"hello\", ttl=5, now=10)\n        self.assertEqual(cache.get(\"a\", now=15, default=\"gone\"), \"gone\")\n\n    def test_stored_none_is_a_valid_value(self):\n        cache = Cache()\n        cache.put(\"a\", None, ttl=5, now=10)\n        sentinel = object()\n        self.assertIsNone(cache.get(\"a\", now=12, default=sentinel))\n        # A missing key with the same sentinel default is distinguishable.\n        self.assertIs(cache.get(\"missing\", now=12, default=sentinel), sentinel)\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"
