ntries_discarded_before_eviction(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=5, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        # \"a\" is expired at now=10; inserting \"c\" should drop \"a\" (expired)\n        # rather than evicting \"b\" (the LRU live entry).\n        cache.put(\"c\", 3, ttl=100, now=10)\n        self.assertNotIn(\"a\", cache._items)\n        self.assertEqual(cache.get(\"b\", now=10), 2)\n        self.assertEqual(cache.get(\"c\", now=10), 3)\n\n    def test_updating_existing_key_does_not_evict(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"a\", 10, ttl=100, now=0)\n        self.assertEqual(cache.get(\"a\", now=0), 10)\n        self.assertEqual(cache.get(\"b\", now=0), 2)\n        self.assertEqual(len(cache._items), 2)\n\n    def test_capacity_one(self):\n        cache = Cache(capacity=1)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        self.assertIsNone(cache.get(\"a\", now=0))\n        self.assertEqual(cache.get(\"b\", now=0), 2)\n\n    def test_expiry_behavior_preserved_with_capacity(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", \"hello\", ttl=5, now=10)\n        self.assertIsNone(cache.get(\"a\", now=15, default=\"gone\"))\n        self.assertNotIn(\"a\", cache._items)\n        cache.put(\"b\", \"x\", ttl=0, now=15)\n        self.assertNotIn(\"b\", cache._items)\n\n\nif __name__ == \"__main__\":"
