ache.get(\"b\", now=4))\n        self.assertEqual(cache.get(\"a\", now=4), 11)\n        self.assertEqual(cache.get(\"c\", now=4), 3)\n\n    def test_missing_get_does_not_change_order(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=10, now=0)\n        cache.put(\"b\", 2, ttl=10, now=1)\n        self.assertIsNone(cache.get(\"zzz\", now=2))\n        cache.put(\"c\", 3, ttl=10, now=3)\n        self.assertIsNone(cache.get(\"a\", now=4))\n        self.assertEqual(cache.get(\"b\", now=4), 2)\n\n    def test_expired_entries_discarded_before_eviction(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=5, now=0)  # expires at 5\n        cache.put(\"b\", 2, ttl=10, now=1)\n        cache.put(\"c\", 3, ttl=10, now=5)  # \"a\" is expired at now=5\n        # \"a\" was expired, so \"b\" (LRU but live) must survive.\n        self.assertEqual(cache.get(\"b\", now=6), 2)\n        self.assertEqual(cache.get(\"c\", now=6), 3)\n        self.assertIsNone(cache.get(\"a\", now=6))\n\n    def test_update_existing_key_does_not_evict(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=10, now=0)\n        cache.put(\"b\", 2, ttl=10, now=1)\n        cache.put(\"a\", 11, ttl=10, now=2)\n        self.assertEqual(cache.get(\"a\", now=3), 11)\n        self.assertEqual(cache.get(\"b\", now=3), 2)\n\n    def test_zero_ttl_put_does_not_evict(self):\n        cache = Cache(capacity=1)\n        cache.put(\"a\", 1, ttl=10, now=0)\n        cache.put(\"b\", 2, ttl=0, now=1)\n        self.assertEqual(cache.get(\"a\", now=2), 1)\n\n    def test_expiry_semantics_preserved_with_capacity(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", \"hello\", ttl=5, now=10)\n        self.assertIsNone(cache.get(\"a\", now=15))\n        cache.put(\"a\", \"hello\", ttl=0, now=16)\n        self.assertIsNone(cache.get(\"a\", now=16))\n\n    def test_lru_order_uses_ordered_store(self):\n        cache = Cache(capacity=3)\n        cache.put(\"