"""A small cache with caller-supplied time, for deterministic tests."""


class Cache:
    def __init__(self, capacity=None):
        if capacity is not None and capacity <= 0:
            raise ValueError("capacity must be a positive integer or None")
        self._capacity = capacity
        # dict preserves insertion order; last item is most recently used.
        self._items = {}

    def put(self, key, value, ttl, now):
        if ttl <= 0:
            self._items.pop(key, None)
            return
        updating = key in self._items
        # Discard entries already expired at `now` before any eviction.
        expired = [k for k, (_, expires) in self._items.items() if now >= expires]
        for k in expired:
            del self._items[k]
        # Re-insert so the key becomes most recently used, even on update.
        self._items.pop(key, None)
        self._items[key] = (value, now + ttl)
        if not updating and self._capacity is not None:
            while len(self._items) > self._capacity:
                self._items.pop(next(iter(self._items)))

    def get(self, key, now, default=None):
        item = self._items.get(key)
        if item is None:
            return default
        value, expires = item
        if now >= expires:
            del self._items[key]
            return default
        # Promote to most recently used.
        del self._items[key]
        self._items[key] = item
        return value

    def get_or_load(self, key, loader, ttl, now):
        sentinel = object()
        value = self.get(key, now, default=sentinel)
        if value is not sentinel:
            return value
        # Miss or expiry: call the loader exactly once. If it raises,
        # propagate without caching anything or evicting another entry.
        value = loader()
        self.put(key, value, ttl=ttl, now=now)
        return value

