                    "newText": "class GetOrLoadTests(unittest.TestCase):\n    def test_returns_cached_value_without_calling_loader(self):\n        cache = Cache()\n        cache.put(\"a\", \"cached\", ttl=100, now=0)\n        calls = []\n        self.assertEqual(cache.get_or_load(\"a\", lambda: calls.append(1) or \"fresh\", ttl=100, now=1), \"cached\")\n        self.assertEqual(calls, [])\n\n    def test_returns_cached_none_without_calling_loader(self):\n        cache = Cache()\n        cache.put(\"a\", None, ttl=100, now=0)\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return \"fresh\"\n\n        self.assertIsNone(cache.get_or_load(\"a\", loader, ttl=100, now=1))\n        self.assertEqual(calls, [])\n\n    def test_successful_get_or_load_promotes_key(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=1)\n        self.assertEqual(cache.get_or_load(\"a\", lambda: 99, ttl=100, now=2), 1)\n        cache.put(\"c\", 3, ttl=100, now=3)\n        self.assertEqual(cache.get(\"a\", now=4), 1)\n        self.assertEqual(cache.get(\"b\", now=4, default=\"gone\"), \"gone\")\n\n    def test_miss_calls_loader_once_and_caches_result(self):\n        cache = Cache()\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return \"loaded\"\n\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=10), \"loaded\")\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=11), \"loaded\")\n        self.assertEqual(len(calls), 1)\n\n    def test_expired_entry_calls_loader_and_stores_new_value(self):\n        cache = Cache()\n        cache.put(\"a\", \"old\", ttl=5, now=10)\n        self.assertEqual(cache.get_or_load(\"a\", lambda: \"new\", ttl=5, now=15), \"new\")\n        self.assertEqual(cache.get(\"a\", now=16), \"new\")\n\n    def test_loader_result_none_is_cached(self):\n        cache = Cache()\n        calls =