     def loader():\n            calls.append(1)\n            return len(calls)\n\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=10), 1)\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=15), 2)\n        self.assertEqual(len(calls), 2)\n\n    def test_loaded_none_is_cached(self):\n        cache = Cache()\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return None\n\n        self.assertIsNone(cache.get_or_load(\"a\", loader, ttl=100, now=0))\n        self.assertIsNone(cache.get_or_load(\"a\", loader, ttl=100, now=1))\n        self.assertEqual(len(calls), 1)\n\n    def test_loader_result_follows_nonpositive_ttl_rule(self):\n        cache = Cache()\n        cache.put(\"a\", \"old\", ttl=100, now=0)\n        sentinel = object()\n        self.assertIsNone(cache.get_or_load(\"a\", lambda: None, ttl=0, now=1))\n        # ttl <= 0 removed the old value and stored nothing.\n        self.assertIs(cache.get(\"a\", now=2, default=sentinel), sentinel)\n\n    def test_loader_result_follows_lru_rules(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=1)\n        self.assertEqual(cache.get_or_load(\"c\", lambda: 3, ttl=100, now=2), 3)\n        sentinel = object()\n        self.assertIs(cache.get(\"a\", now=3, default=sentinel), sentinel)\n        self.assertEqual(cache.get(\"b\", now=3), 2)\n        self.assertEqual(cache.get(\"c\", now=3), 3)\n\n    def test_loader_exception_propagates_without_side_effects(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=1)\n        boom = RuntimeError(\"boom\")\n\n        def loader():\n            raise boom\n\n        with self.assertRaises(RuntimeError) as ctx:\n            cache.get_or_load(\"c\", loader, ttl=100, now=2)\n        self.assertIs(ctx.exception, boom)\n        # No eviction of unrelated live entries, and nothing cached for \"c\".\n        self.assertEqual(cache.get(\"a\", now=3), 1)\n        self.assertEqual(cache.get(\"b\", now=3), 2)\n        sentinel = object()\n        self.assertIs(cache.get(\"c\", now=3, default=sentinel), sentinel)\n\n    def test_loader_exception_on_update_keeps_old_value(self):\n        cache = Cache(capacity=1)\n        cache.put(\"a\", \"old\", ttl=100, now=0)\n\n        def loader():\n            raise KeyError(\"nope\")\n\n        with self.assertRaises(KeyError):\n            cache.get_or_load(\"b\", loader, ttl=100, now=1)\n        self.assertEqual(cache.get(\"a\", now=2), \"old\")\n\n\n",
