                    "newText": "    def test_expiry_behavior_preserved_with_capacity(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", \"hello\", ttl=5, now=10)\n        self.assertEqual(cache.get(\"a\", now=14), \"hello\")\n        self.assertIsNone(cache.get(\"a\", now=15))\n        self.assertNotIn(\"a\", cache._items)\n        cache.put(\"b\", \"x\", ttl=0, now=15)\n        self.assertIsNone(cache.get(\"b\", now=15))\n\n\nclass CacheGetOrLoadTests(unittest.TestCase):\n    class Boom(Exception):\n        pass\n\n    def test_returns_cached_value_without_calling_loader(self):\n        cache = Cache()\n        cache.put(\"a\", \"cached\", ttl=100, now=0)\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return \"loaded\"\n\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=100, now=1), \"cached\")\n        self.assertEqual(calls, [])\n\n    def test_cached_none_is_returned_without_calling_loader(self):\n        cache = Cache()\n        cache.put(\"a\", None, ttl=100, now=0)\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return \"loaded\"\n\n        self.assertIsNone(cache.get_or_load(\"a\", loader, ttl=100, now=1))\n        self.assertEqual(calls, [])\n\n    def test_cached_hit_is_promoted(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        self.assertEqual(cache.get_or_load(\"a\", lambda: \"x\", ttl=100, now=0), 1)\n        cache.put(\"c\", 3, ttl=100, now=0)\n        self.assertEqual(cache.get(\"a\", now=0), 1)\n        self.assertIsNone(cache.get(\"b\", now=0))\n\n    def test_miss_calls_loader_once_and_caches_result(self):\n        cache = Cache()\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return \"loaded\"\n\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=10), \"loaded\")\n        self.assertEqual(calls, [1])\n        self.assertEqual(cache.get(\"a\", now=14), \"loaded\")\n        self.assertEqual(calls, [1])\n\n    def test_expired_entry_calls_loader_once_and_replaces(self):\n        cache = Cache()\n        cache.put(\"a\", \"stale\", ttl=5, now=0)\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return \"fresh\"\n\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=5), \"fresh\")\n        self.assertEqual(calls, [1])\n        self.assertEqual(cache.get(\"a\", now=9), \"fresh\")\n\n    def test_loaded_none_is_cached(self):\n        cache = Cache()\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return None\n\n        self.assertIsNone(cache.get_or_load(\"a\", loader, ttl=100, now=0))\n        self.assertIsNone(cache.get_or_load(\"a\", loader, ttl=100, now=1))\n        self.assertEqual(calls, [1])\n\n    def test_loader_result_follows_nonpositive_ttl_rule(self):\n        cache = Cache()\n        self.assertEqual(cache.get_or_load(\"a\", lambda: \"x\", ttl=0, now=0), \"x\")\n        self.assertNotIn(\"a\", cache._items)\n\n    def test_loader_result_follows_lru_eviction_rules(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        self.assertEqual(cache.get_or_load(\"c\", lambda: 3, ttl=100, now=0), 3)\n        self.assertIsNone(cache.get(\"a\", now=0))\n        self.assertEqual(cache.get(\"b\", now=0), 2)\n        self.assertEqual(cache.get(\"c\", now=0), 3)\n\n    def test_loader_exception_propagates_without_caching(self):\n        cache = Cache()\n\n        def loader():\n            raise CacheGetOrLoadTests.Boom(\"kaboom\")\n\n        with self.assertRaises(CacheGetOrLoadTests.Boom):\n            cache.get_or_load(\"a\", loader, ttl=100, now=0)\n        self.assertNotIn(\"a\", cache._items)\n        self.assertEqual(cache._items, {})\n\n    def test_loader_exception_does_not_evict_unrelated_live_entry(self):\n        cache = Cache(capacity=1)\n        cache.put(\"a\", 1, ttl=100, now=0)\n\n        def loader():\n            raise CacheGetOrLoadTests.Boom(\"kaboom\")\n\n        with self.assertRaises(CacheGetOrLoadTests.Boom):\n            cache.get_or_load(\"b\", loader, ttl=100, now=0)\n        self.assertEqual(cache.get(\"a\", now=0), 1)\n\n    def test_loader_receives_no_arguments(self):\n        cache = Cache()\n\n        def loader():\n            return \"loaded\"\n\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=100, now=0), \"loaded\")\n",
