\"c\", 3, ttl=100, now=3)\n        # \"a\" is still the LRU entry and must be the one evicted.\n        self.assertIsNone(cache.get(\"a\", now=4))\n        self.assertEqual(cache.get(\"b\", now=4), 2)\n        self.assertEqual(cache.get(\"c\", now=4), 3)\n\n    def test_expired_entries_discarded_before_eviction(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=5, now=0)\n        cache.put(\"b\", 2, ttl=100, now=1)\n        # \"a\" is expired at now=10; inserting \"c\" should discard \"a\", not \"b\".\n        cache.put(\"c\", 3, ttl=100, now=10)\n        self.assertIsNone(cache.get(\"a\", now=10))\n        self.assertEqual(cache.get(\"b\", now=10), 2)\n        self.assertEqual(cache.get(\"c\", now=10), 3)\n\n    def test_updating_existing_key_does_not_evict(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=1)\n        cache.put(\"a\", 10, ttl=100, now=2)\n        self.assertEqual(cache.get(\"a\", now=3), 10)\n        self.assertEqual(cache.get(\"b\", now=3), 2)\n\n    def test_zero_ttl_removal_still_works_with_capacity(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"a\", 2, ttl=0, now=1)\n        self.assertIsNone(cache.get(\"a\", now=2))\n\n\nif __name__ == \"__main__\":"
