              "newText": "class GetOrLoadTests(unittest.TestCase):\n    def test_hit_does_not_call_loader(self):\n        cache = Cache()\n        cache.put(\"a\", \"cached\", ttl=10, now=0)\n\n        def loader():\n            raise AssertionError(\"loader must not be called on a hit\")\n\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=10, now=1), \"cached\")\n\n    def test_hit_with_none_value_does_not_call_loader(self):\n        cache = Cache()\n        cache.put(\"a\", None, ttl=10, now=0)\n\n        def loader():\n            raise AssertionError(\"loader must not be called for a cached None\")\n\n        self.assertIsNone(cache.get_or_load(\"a\", loader, ttl=10, now=1))\n\n    def test_hit_promotes_key(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=1)\n        self.assertEqual(cache.get_or_load(\"a\", lambda: 99, ttl=100, now=2), 1)\n        cache.put(\"c\", 3, ttl=100, now=3)\n        # \"a\" was promoted, so \"b\" is the LRU victim.\n        self.assertIsNone(cache.get(\"b\", now=4))\n        self.assertEqual(cache.get(\"a\", now=4), 1)\n\n    def test_miss_calls_loader_once_and_caches(self):\n        cache = Cache()\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return \"loaded\"\n\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=10, now=0), \"loaded\")\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=10, now=1), \"loaded\")\n        self.assertEqual(len(calls), 1)\n\n    def test_expired_entry_calls_loader_again(self):\n        cache = Cache()\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return len(calls)\n\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=0), 1)\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=5), 2)\n        self.assertEqual(len(calls), 2)\n\n    def test_loaded_none_is_cached(self):\n        