                    "newText": "class CapacityTests(unittest.TestCase):\n    def test_invalid_capacity_raises(self):\n        for bad in (0, -1, -100):\n            with self.subTest(capacity=bad):\n                with self.assertRaises(ValueError):\n                    Cache(capacity=bad)\n\n    def test_default_is_unbounded(self):\n        cache = Cache()\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"c\", 3, ttl=100, now=0)\n        self.assertEqual(cache.get(\"a\", now=1), 1)\n        self.assertEqual(cache.get(\"b\", now=1), 2)\n        self.assertEqual(cache.get(\"c\", now=1), 3)\n\n    def test_evicts_least_recently_used(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"c\", 3, ttl=100, now=0)\n        sentinel = object()\n        self.assertIs(cache.get(\"a\", now=1, default=sentinel), sentinel)\n        self.assertEqual(cache.get(\"b\", now=1), 2)\n        self.assertEqual(cache.get(\"c\", now=1), 3)\n\n    def test_get_promotes_key(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        self.assertEqual(cache.get(\"a\", now=1), 1)\n        cache.put(\"c\", 3, ttl=100, now=1)\n        self.assertEqual(cache.get(\"a\", now=2), 1)\n        self.assertIsNone(cache.get(\"b\", now=2))\n\n    def test_put_promotes_key(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"a\", 10, ttl=100, now=1)\n        cache.put(\"c\", 3, ttl=100, now=2)\n        self.assertEqual(cache.get(\"a\", now=3), 10)\n        self.assertIsNone(cache.get(\"b\", now=3))\n\n    def test_missing_get_does_not_change_order(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        self.assertIsNone(cache.get(\"zzz\", now=1))\n        # \"a\" must still be the LRU entry and be evicted by the next put.\n        cache.put(\"c\", 3, ttl=100, now=1)\n        self.assertIsNone(cache.get(\"a\", now=2))\n        self.assertEqual(cache.get(\"b\", now=2), 2)\n\n    def test_expired_entries_discarded_before_eviction(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=5, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        # \"a\" is expired at now=5; inserting \"c\" should discard it instead of\n        # evicting the LRU live entry \"b\".\n        cache.put(\"c\", 3, ttl=100, now=5)\n        self.assertEqual(cache.get(\"b\", now=6), 2)\n        self.assertEqual(cache.get(\"c\", now=6), 3)\n        self.assertIsNone(cache.get(\"a\", now=6))\n\n    def test_update_existing_key_does_not_evict(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"a\", 10, ttl=100, now=1)\n        self.assertEqual(cache.get(\"a\", now=2), 10)\n        self.assertEqual(cache.get(\"b\", now=2), 2)\n\n    def test_expiry_semantics_under_capacity(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", \"hello\", ttl=5, now=10)\n        self.assertIsNone(cache.get(\"a\", now=15))\n        self.assertNotIn(\"a\", cache._items)\n        cache.put(\"b\", \"x\", ttl=0, now=15)\n        self.assertNotIn(\"b\", cache._items)\n\n\nif __name__ == \"__main__\":"
