                    "newText": "class GetOrLoadTests(unittest.TestCase):\n    def test_returns_cached_value_without_calling_loader(self):\n        cache = Cache()\n        cache.put(\"a\", \"cached\", ttl=100, now=0)\n        calls = []\n        self.assertEqual(cache.get_or_load(\"a\", lambda: calls.append(1) or \"fresh\", ttl=100, now=1), \"cached\")\n        self.assertEqual(calls, [])\n\n    def test_stored_none_is_a_hit_and_skips_loader(self):\n        cache = Cache()\n        cache.put(\"a\", None, ttl=100, now=0)\n        calls = []\n        self.assertIsNone(cache.get_or_load(\"a\", lambda: calls.append(1) or \"fresh\", ttl=100, now=1))\n        self.assertEqual(calls, [])\n\n    def test_hit_promotes_key(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        self.assertEqual(cache.get_or_load(\"a\", lambda: \"x\", ttl=100, now=1), 1)\n        cache.put(\"c\", 3, ttl=100, now=1)\n        self.assertEqual(cache.get(\"a\", now=2), 1)\n        self.assertIsNone(cache.get(\"b\", now=2))\n\n    def test_miss_calls_loader_once_and_caches(self):\n        cache = Cache()\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return \"loaded\"\n\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=10), \"loaded\")\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=11), \"loaded\")\n        self.assertEqual(len(calls), 1)\n        # Respects TTL: expires at now >= 15.\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=15), \"loaded\")\n        self.assertEqual(len(calls), 2)\n\n    def test_loader_returning_none_is_cached(self):\n        cache = Cache()\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return None\n\n        self.assertIsNone(cache.get_or_load(\"a\", loader, ttl=100, now=0))\n        self.assertIsNone(cache.get_or_load(\"a\", loader, ttl=100, now=1))\n        self.assertEqual(len(calls), 1)\n\n    def test_loader_result_follows_ttl_and_lru_rules(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        # Inserting \"c\" evicts LRU \"a\".\n        self.assertEqual(cache.get_or_load(\"c\", lambda: 3, ttl=100, now=1), 3)\n        self.assertIsNone(cache.get(\"a\", now=2))\n        self.assertEqual(cache.get(\"b\", now=2), 2)\n        self.assertEqual(cache.get(\"c\", now=2), 3)\n        # Nonpositive ttl means the loaded value is not stored.\n        self.assertIsNone(cache.get_or_load(\"d\", lambda: 4, ttl=0, now=2))\n        self.assertNotIn(\"d\", cache._items)\n\n    def test_loader_exception_propagates_without_side_effects(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        boom = RuntimeError(\"boom\")\n\n        def loader():\n            raise boom\n\n        with self.assertRaises(RuntimeError) as ctx:\n            cache.get_or_load(\"missing\", loader, ttl=100, now=1)\n        self.assertIs(ctx.exception, boom)\n        # No eviction of unrelated live entries, nothing cached.\n        self.assertEqual(cache.get(\"a\", now=2), 1)\n        self.assertEqual(cache.get(\"b\", now=2), 2)\n        self.assertNotIn(\"missing\", cache._items)\n\n\nif __name__ == \"__main__\":",
