st_missing_get_does_not_change_order(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        self.assertIsNone(cache.get(\"zzz\", now=1))\n        cache.put(\"c\", 3, ttl=100, now=1)\n        # a must still be the LRU victim; a missing get must not promote anything.\n        self.assertIsNone(cache.get(\"a\", now=2))\n        self.assertEqual(cache.get(\"b\", now=2), 2)\n        self.assertEqual(cache.get(\"c\", now=2), 3)\n\n    def test_expired_entries_discarded_before_eviction(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=5, now=0)  # expires at 5\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"c\", 3, ttl=100, now=5)  # a is expired at now=5\n        # a was evicted as expired, not b as LRU.\n        self.assertEqual(cache.get(\"b\", now=6), 2)\n        self.assertEqual(cache.get(\"c\", now=6), 3)\n        self.assertIsNone(cache.get(\"a\", now=6))\n\n    def test_update_existing_key_does_not_evict(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"a\", 10, ttl=100, now=1)  # update, not an insertion\n        self.assertEqual(cache.get(\"a\", now=2), 10)\n        self.assertEqual(cache.get(\"b\", now=2), 2)\n\n    def test_update_expired_key_counts_as_insertion(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=5, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"a\", 10, ttl=100, now=5)  # a was expired; reinsertion, b survives\n        self.assertEqual(cache.get(\"a\", now=6), 10)\n        self.assertEqual(cache.get(\"b\", now=6), 2)\n\n    def test_expired_key_update_does_not_evict_other(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=5, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"c\", 3, ttl=100, now=5)  # a purged as expired; 