                    "newText": "class GetOrLoadTests(unittest.TestCase):\n    def test_returns_cached_value_without_calling_loader(self):\n        cache = Cache()\n        cache.put(\"a\", \"cached\", ttl=100, now=0)\n        calls = []\n        self.assertEqual(cache.get_or_load(\"a\", lambda: calls.append(1) or \"fresh\", ttl=100, now=1), \"cached\")\n        self.assertEqual(calls, [])\n\n    def test_returns_promoted_cached_value_at_capacity(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        # get_or_load hit promotes a, so b becomes the LRU victim.\n        self.assertEqual(cache.get_or_load(\"a\", lambda: \"x\", ttl=100, now=1), 1)\n        cache.put(\"c\", 3, ttl=100, now=1)\n        self.assertIsNone(cache.get(\"b\", now=2))\n        self.assertEqual(cache.get(\"a\", now=2), 1)\n\n    def test_stored_none_is_returned_without_calling_loader(self):\n        cache = Cache()\n        cache.put(\"a\", None, ttl=100, now=0)\n        calls = []\n        self.assertIsNone(cache.get_or_load(\"a\", lambda: calls.append(1) or \"fresh\", ttl=100, now=1))\n        self.assertEqual(calls, [])\n\n    def test_miss_calls_loader_once_and_caches(self):\n        cache = Cache()\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return \"loaded\"\n\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=10), \"loaded\")\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=11), \"loaded\")\n        self.assertEqual(len(calls), 1)\n        # Respects TTL: expires at 15 (now >= expiry).\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=15), \"loaded\")\n        self.assertEqual(len(calls), 2)\n\n    def test_expired_entry_calls_loader_again(self):\n        cache = Cache()\n        cache.put(\"a\", \"old\", ttl=5, now=0)\n        self.assertEqual(cache.get_or_load(\"a\", lambda: \"new\", ttl=5, now=5), \"new\")\n        self.assertEqual(cache.get(\"a\", now=6), \"new\")\n\n    def test_loader_result_follows_lru_eviction(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        self.assertEqual(cache.get_or_load(\"c\", lambda: 3, ttl=100, now=0), 3)\n        self.assertIsNone(cache.get(\"a\", now=1))  # LRU victim evicted\n        self.assertEqual(cache.get(\"b\", now=1), 2)\n        self.assertEqual(cache.get(\"c\", now=1), 3)\n\n    def test_loader_none_result_is_cached(self):\n        cache = Cache()\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return None\n\n        self.assertIsNone(cache.get_or_load(\"a\", loader, ttl=100, now=0))\n        self.assertIsNone(cache.get_or_load(\"a\", loader, ttl=100, now=1))\n        self.assertEqual(len(calls), 1)\n\n    def test_loader_exception_propagates_without_caching(self):\n        cache = Cache()\n\n        class Boom(Exception):\n            pass\n\n        def loader():\n            raise Boom()\n\n        with self.assertRaises(Boom) as ctx:\n            cache.get_or_load(\"a\", loader, ttl=100, now=0)\n        self.assertIsInstance(ctx.exception, Boom)\n        self.assertNotIn(\"a\", cache._items)\n\n    def test_loader_exception_does_not_evict_unrelated_live_entry(self):\n        cache = Cache(capacity=1)\n        cache.put(\"keep\", \"live\", ttl=100, now=0)\n\n        def loader():\n            raise RuntimeError(\"boom\")\n\n        with self.assertRaises(RuntimeError):\n            cache.get_or_load(\"a\", loader, ttl=100, now=0)\n        self.assertEqual(cache.get(\"keep\", now=1), \"live\")\n\n    def test_loader_exception_after_expiry_only_removes_expired_entry(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", \"old\", ttl=5, now=0)  # expired at now=5\n        cache.put(\"keep\", \"live\", ttl=100, now=0)\n\n        def loader():\n            raise RuntimeError(\"boom\"