"""A small cache with caller-supplied time, for deterministic tests."""

from collections import OrderedDict


class Cache:
    def __init__(self, capacity=None):
        if capacity is not None and capacity <= 0:
            raise ValueError("capacity must be a positive integer or None")
        self._capacity = capacity
        self._items = OrderedDict()  # key -> (value, expires); order = LRU order

    def _purge_expired(self, now):
        expired = [k for k, (_, expires) in self._items.items() if now >= expires]
        for key in expired:
            del self._items[key]

    def put(self, key, value, ttl, now):
        if ttl <= 0:
            self._items.pop(key, None)
            return
        updating = key in self._items and now < self._items[key][1]
        # Discard entries expired as of `now` before considering eviction.
        self._purge_expired(now)
        self._items[key] = (value, now + ttl)
        self._items.move_to_end(key)
        if self._capacity is not None and not updating:
            while len(self._items) > self._capacity:
                self._items.popitem(last=False)

    def get(self, key, now, default=None):
        item = self._items.get(key)
        if item is None:
            return default
        value, expires = item
        if now >= expires:
            del self._items[key]
            return default
        self._items.move_to_end(key)
        return value

    def get_or_load(self, key, loader, ttl, now):
        sentinel = object()
        value = self.get(key, now, default=sentinel)
        if value is not sentinel:
            return value
        # Miss or expiry: load once, then store via the normal put rules.
        value = loader()
        self.put(key, value, ttl=ttl, now=now)
        return value

