                    "newText": "    def test_stored_none_is_a_valid_value(self):\n        cache = Cache()\n        cache.put(\"a\", None, ttl=5, now=10)\n        sentinel = object()\n        self.assertIsNone(cache.get(\"a\", now=12, default=sentinel))\n        # A missing key returns the default instead.\n        self.assertIs(cache.get(\"missing\", now=12, default=sentinel), sentinel)\n\n\nclass CacheCapacityTests(unittest.TestCase):\n    def test_zero_capacity_raises(self):\n        with self.assertRaises(ValueError):\n            Cache(capacity=0)\n\n    def test_negative_capacity_raises(self):\n        with self.assertRaises(ValueError):\n            Cache(capacity=-1)\n\n    def test_none_capacity_is_unbounded(self):\n        cache = Cache(capacity=None)\n        for i in range(100):\n            cache.put(i, i, ttl=100, now=0)\n        self.assertEqual(len(cache._items), 100)\n\n    def test_evicts_least_recently_used(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"c\", 3, ttl=100, now=0)\n        self.assertIsNone(cache.get(\"a\", now=1))\n        self.assertEqual(cache.get(\"b\", now=1), 2)\n        self.assertEqual(cache.get(\"c\", now=1), 3)\n\n    def test_get_promotes_key(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        self.assertEqual(cache.get(\"a\", now=1), 1)\n        cache.put(\"c\", 3, ttl=100, now=1)\n        # \"a\" was promoted by get, so \"b\" is evicted instead.\n        self.assertEqual(cache.get(\"a\", now=2), 1)\n        self.assertIsNone(cache.get(\"b\", now=2))\n\n    def test_put_promotes_key(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"a\", 10, ttl=100, now=1)\n        cache.put(\"c\", 3, ttl=100, now=2)\n        self.assertEqual(cache.get(\"a\", now=3), 10)\n        self.assertIsNone(cache.get(\"b\", now=3))\n\n    def test_missing_get_does_not_change_order(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        self.assertIsNone(cache.get(\"zzz\", now=1))\n        cache.put(\"c\", 3, ttl=100, now=1)\n        # Order unchanged by the missing get: \"a\" is still LRU.\n        self.assertIsNone(cache.get(\"a\", now=2))\n        self.assertEqual(cache.get(\"b\", now=2), 2)\n\n    def test_expired_entries_discarded_before_eviction(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=5, now=0)   # expires at 5\n        cache.put(\"b\", 2, ttl=100, now=0)\n        # At now=10, \"a\" is expired; put of \"c\" discards it without evicting \"b\".\n        cache.put(\"c\", 3, ttl=100, now=10)\n        self.assertIsNone(cache.get(\"a\", now=10))\n        self.assertEqual(cache.get(\"b\", now=10), 2)\n        self.assertEqual(cache.get(\"c\", now=10), 3)\n\n    def test_updating_existing_key_does_not_evict(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"b\", 20, ttl=100, now=1)\n        self.assertEqual(cache.get(\"a\", now=2), 1)\n        self.assertEqual(cache.get(\"b\", now=2), 20)\n        self.assertEqual(len(cache._items), 2)\n\n    def test_put_nonpositive_ttl_does_not_evict(self):\n        cache = Cache(capacity=1)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=0, now=1)\n        self.assertEqual(cache.get(\"a\", now=2), 1)\n\n    def test_expiry_behavior_preserved_with_capacity(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", \"hello\", ttl=5, now=10)\n        self.assertEqual(cache.get(\"a\", now=14), \"hello\")\n        self.assertIsNone(cache.get(\"a\", now=15))\n        self.assertNotIn(\"a\", cache._items)",
