                    "newText": "    def test_expiry_behavior_preserved_with_capacity(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", \"hello\", ttl=5, now=10)\n        self.assertEqual(cache.get(\"a\", now=14), \"hello\")\n        self.assertIsNone(cache.get(\"a\", now=15))\n        self.assertNotIn(\"a\", cache._items)\n\n\nclass GetOrLoadTests(unittest.TestCase):\n    def test_hit_does_not_call_loader(self):\n        cache = Cache()\n        cache.put(\"a\", \"cached\", ttl=10, now=0)\n\n        def loader():\n            raise AssertionError(\"loader must not be called\")\n\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=10, now=5), \"cached\")\n\n    def test_stored_none_hit_does_not_call_loader(self):\n        cache = Cache()\n        cache.put(\"a\", None, ttl=10, now=0)\n\n        def loader():\n            raise AssertionError(\"loader must not be called\")\n\n        self.assertIsNone(cache.get_or_load(\"a\", loader, ttl=10, now=5))\n\n    def test_hit_promotes_key(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        self.assertEqual(cache.get_or_load(\"a\", lambda: 99, ttl=100, now=1), 1)\n        cache.put(\"c\", 3, ttl=100, now=2)\n        # \"a\" was promoted, so \"b\" is evicted instead.\n        self.assertEqual(cache.get(\"a\", now=3), 1)\n        self.assertIsNone(cache.get(\"b\", now=3))\n\n    def test_miss_calls_loader_once_and_caches(self):\n        cache = Cache()\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return \"loaded\"\n\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=10, now=0), \"loaded\")\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=10, now=1), \"loaded\")\n        self.assertEqual(len(calls), 1)\n\n    def test_expired_entry_calls_loader_again(self):\n        cache = Cache()\n        calls = []\n\n        def loader():\n            calls.append(1)\n            return len(calls)\n\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=0), 1)\n        self.assertEqual(cache.get_or_load(\"a\", loader, ttl=5, now=5), 2)\n        self.assertEqual(len(calls), 2)\n\n    def test_loader_result_follows_ttl_rules(self):\n        cache = Cache()\n        self.assertIsNone(cache.get_or_load(\"a\", lambda: \"x\", ttl=0, now=0))\n        self.assertNotIn(\"a\", cache._items)\n        self.assertIsNone(cache.get_or_load(\"b\", lambda: \"y\", ttl=-1, now=0))\n        self.assertNotIn(\"b\", cache._items)\n\n    def test_loader_result_follows_lru_rules(self):\n        cache = Cache(capacity=1)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        self.assertEqual(cache.get_or_load(\"b\", lambda: 2, ttl=100, now=0), 2)\n        self.assertIsNone(cache.get(\"a\", now=1))\n        self.assertEqual(cache.get(\"b\", now=1), 2)\n\n    def test_loader_exception_propagates_without_caching(self):\n        cache = Cache()\n        boom = RuntimeError(\"boom\")\n\n        def loader():\n            raise boom\n\n        with self.assertRaises(RuntimeError) as ctx:\n            cache.get_or_load(\"a\", loader, ttl=10, now=0)\n        self.assertIs(ctx.exception, boom)\n        self.assertNotIn(\"a\", cache._items)\n        self.assertIsNone(cache.get(\"a\", now=1))\n\n    def test_loader_exception_does_not_evict_live_entry(self):\n        cache = Cache(capacity=1)\n        cache.put(\"a\", 1, ttl=100, now=0)\n\n        def loader():\n            raise RuntimeError(\"boom\")\n\n        with self.assertRaises(RuntimeError):\n            cache.get_or_load(\"b\", loader, ttl=100, now=1)\n        # The unrelated live entry \"a\" must survive.\n        self.assertEqual(cache.get(\"a\", now=2), 1)\n\n\nif __name__ == \"__main__\":",
