lf.assertEqual(cache.get(\"a\", now=15, default=0), 0)\n\n    def test_stored_none_is_a_valid_value(self):\n        cache = Cache()\n        cache.put(\"a\", None, ttl=5, now=10)\n        sentinel = object()\n        self.assertIsNone(cache.get(\"a\", now=12, default=sentinel))\n\n    def test_not_expired_just_before_expiry(self):\n        cache = Cache()\n        cache.put(\"a\", \"hello\", ttl=5, now=10)\n        self.assertEqual(cache.get(\"a\", now=14.999), \"hello\")\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"
