                "text": "import unittest\n\nfrom cache import Cache\n\n\nclass CacheTests(unittest.TestCase):\n    def test_round_trip(self):\n        cache = Cache()\n        cache.put(\"a\", \"hello\", ttl=5, now=10)\n        self.assertEqual(cache.get(\"a\", now=14), \"hello\")\n        self.assertIsNone(cache.get(\"a\", now=16))\n\n    def test_expired_at_exact_expiry_time(self):\n        cache = Cache()\n        cache.put(\"a\", \"hello\", ttl=5, now=10)\n        self.assertIsNone(cache.get(\"a\", now=15))\n\n    def test_expiry_removes_entry(self):\n        cache = Cache()\n        cache.put(\"a\", \"hello\", ttl=5, now=10)\n        self.assertIsNone(cache.get(\"a\", now=15))\n        # Entry should be gone; re-adding works and internal state is clean.\n        cache.put(\"a\", \"world\", ttl=5, now=15)\n        self.assertEqual(cache.get(\"a\", now=16), \"world\")\n\n    def test_put_with_zero_ttl_removes_existing_value(self):\n        cache = Cache()\n        cache.put(\"a\", \"hello\", ttl=5, now=10)\n        cache.put(\"a\", \"new\", ttl=0, now=10)\n        self.assertIsNone(cache.get(\"a\", now=10))\n\n    def test_put_with_negative_ttl_removes_existing_value(self):\n        cache = Cache()\n        cache.put(\"a\", \"hello\", ttl=5, now=10)\n        cache.put(\"a\", \"new\", ttl=-1, now=10)\n        self.assertIsNone(cache.get(\"a\", now=10))\n\n    def test_put_with_nonpositive_ttl_does_not_store_new_value(self):\n        cache = Cache()\n        cache.put(\"a\", \"new\", ttl=0, now=10)\n        self.assertIsNone(cache.get(\"a\", now=10))\n        cache.put(\"b\", \"new\", ttl=-3, now=10)\n        self.assertIsNone(cache.get(\"b\", now=10))\n\n    def test_get_preserves_falsey_default(self):\n        cache = Cache()\n        self.assertEqual(cache.get(\"missing\", now=0, default=0), 0)\n        self.assertEqual(cache.get(\"missing\", now=0, default=\"\"), \"\")\n        self.assertIs(cache.get(\"missing\", now=0, default=False), False)\n\n    def test_get_returns_falsey_default_when_expired(self):\n        cache = Cache()\n        cache.put(\"a\", \"hello\", ttl=5, now=10)\n        self.assertEqual(cache.get(\"a\", now=15, default=\"gone\"), \"gone\")\n\n    def test_stored_none_is_a_valid_value(self):\n        cache = Cache()\n        cache.put(\"a\", None, ttl=5, now=10)\n        sentinel = object()\n        self.assertIsNone(cache.get(\"a\", now=12, default=sentinel))\n\n    def test_missing_key_returns_default_not_none(self):\n        cache = Cache()\n        sentinel = object()\n        self.assertIs(cache.get(\"missing\", now=0, default=sentinel), sentinel)\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"
