cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"a\", 10, ttl=100, now=1)\n        cache.put(\"c\", 3, ttl=100, now=2)\n        self.assertIsNone(cache.get(\"b\", now=2))\n        self.assertEqual(cache.get(\"a\", now=2), 10)\n        self.assertEqual(cache.get(\"c\", now=2), 3)\n\n    def test_missing_get_does_not_change_order(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        self.assertIsNone(cache.get(\"zzz\", now=1))\n        # Order must be unchanged: \"a\" is still the LRU victim.\n        cache.put(\"c\", 3, ttl=100, now=1)\n        self.assertIsNone(cache.get(\"a\", now=1))\n        self.assertEqual(cache.get(\"b\", now=1), 2)\n\n    def test_expired_get_does_not_promote_others(self):\n        # A get that returns default (expired) must not disturb other keys' order.\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=5, now=0)\n        self.assertIsNone(cache.get(\"b\", now=10))\n        cache.put(\"c\", 3, ttl=100, now=10)\n        self.assertEqual(cache.get(\"a\", now=10), 1)\n\n    def test_expired_entries_discarded_before_eviction(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=5, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        # \"a\" is expired at now=10; inserting \"c\" should drop \"a\", not \"b\".\n        cache.put(\"c\", 3, ttl=100, now=10)\n        self.assertIsNone(cache.get(\"a\", now=10))\n        self.assertEqual(cache.get(\"b\", now=10), 2)\n        self.assertEqual(cache.get(\"c\", now=10), 3)\n        self.assertEqual(len(cache._items), 2)\n\n    def test_updating_existing_key_does_not_evict(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"a\", 10, ttl=100, now=1)\n        self.assertEqual(cache.get(\"a\", now=1), 10)\n        self.assertEqual(cache.get(\"b\", now=1), 2)\n        self.assertEqual(len(cache._items), 2)\n\n    def test_capacity_one_repeated_update_keeps_key(self):\n        cache = Cache(capacity=1)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"a\", 2, ttl=100, now=1)\n        cache.put(\"a\", 3, ttl=100, now=2)\n        self.assertEqual(cache.get(\"a\", now=2), 3)\n        self.assertEqual(len(cache._items), 1)\n\n    def test_expired_new_key_does_not_evict_when_expired_cleanup_suffices(self):\n        # Inserting a key that is itself already expired must not evict a live key.\n        cache = Cache(capacity=1)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=1, now=0)\n        self.assertEqual(cache.get(\"a\", now=1), 1)\n\n    def test_put_nonpositive_ttl_with_capacity_removes_without_evicting(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"a\", 9, ttl=0, now=1)\n        self.assertIsNone(cache.get(\"a\", now=1))\n        self.assertEqual(cache.get(\"b\", now=1), 2)\n\n    def test_capacity_eviction_respects_expiry_semantics(self):\n        # An entry expiring exactly at `now` counts as expired for cleanup.\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=5, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        cache.put(\"c\", 3, ttl=100, now=5)\n        self.assertIsNone(cache.get(\"a\", now=5))\n        self.assertEqual(cache.get(\"b\", now=5), 2)\n\n    def test_capacity_stored_none_value_survives(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", None, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        sentinel = object()\n        self.assertIsNone(cache.get(\"a\", now=1, default=sentinel))\n        self.assertEqual(cache.get(\"b\", now=1), 2)\n"
