ertRaises(RuntimeError):\n            cache.get_or_load(\"b\", loader, ttl=100, now=1)\n        self.assertEqual(cache.get(\"a\", now=1), 1)\n\n    def test_load_respects_lru_capacity(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        self.assertEqual(cache.get_or_load(\"c\", lambda: 3, ttl=100, now=1), 3)\n        self.assertIsNone(cache.get(\"a\", now=1))\n        self.assertEqual(cache.get(\"b\", now=1), 2)\n        self.assertEqual(cache.get(\"c\", now=1), 3)\n\n    def test_load_discards_expired_before_evicting(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=5, now=0)\n        cache.put(\"b\", 2, ttl=100, now=0)\n        self.assertEqual(cache.get_or_load(\"c\", lambda: 3, ttl=100, now=10), 3)\n        self.assertIsNone(cache.get(\"a\", now=10))\n        self.assertEqual(cache.get(\"b\", now=10), 2)\n        self.assertEqual(cache.get(\"c\", now=10), 3)\n\n    def test_load_updates_existing_key_without_evicting(self):\n        cache = Cache(capacity=2)\n        cache.put(\"a\", 1, ttl=100, now=0)\n        cache.put(\"b\", 2, ttl=5, now=0)  # expires at 5\n        # \"b\" is expired at now=5; loading \"b\" must not evict \"a\".\n        self.assertEqual(cache.get_or_load(\"b\", lambda: 20, ttl=100, now=5), 20)\n        self.assertEqual(cache.get(\"a\", now=5), 1)\n        self.assertEqual(cache.get(\"b\", now=5), 20)\n",
